function localizeDPlayer(mount:HTMLElement){
  const translations:Record<string,string>={'Set danmaku color':'弾幕の色','Set danmaku type':'弾幕の種類','Top':'上','Rolling':'スクロール','Bottom':'下','Input danmaku, hit Enter':'弾幕を入力（Enterで送信）','Setting':'設定','Danmaku is loading':'弾幕を読み込み中','Show danmaku':'弾幕を表示','Opacity for danmaku':'弾幕の不透明度','Unlimited danmaku':'弾幕を無制限に表示','Speed':'再生速度','Loop':'ループ再生','Send':'送信'}
  const translate=()=>{
    const walker=document.createTreeWalker(mount,NodeFilter.SHOW_TEXT)
    while(walker.nextNode()){const node=walker.currentNode;const key=node.textContent?.trim()||'';if(translations[key])node.textContent=node.textContent!.replace(key,translations[key])}
    mount.querySelectorAll<HTMLElement>('input,button,[data-balloon],[title]').forEach(el=>{
      for(const attr of ['placeholder','data-balloon','title','aria-label']){const value=el.getAttribute(attr);if(value&&translations[value])el.setAttribute(attr,translations[value])}
    })
  }
  translate()
  const observer=new MutationObserver(translate);observer.observe(mount,{childList:true,subtree:true,characterData:true})
