watch([chatKind,showDeleted],async()=>{if(!playing.value)return;await loadChat();try{reloadDanmaku()}catch{}});watch(playing,async v=>{if(v){timelineItems.value=[];fetch(`${base}/videos/${v.id}/timeline`).then(r=>r.ok?r.json():{items:[]}).then(d=>timelineItems.value=d.items||[]);transcriptPage.value=0;transcriptQuery.value='';await Promise.all([loadTranscript(),loadSummary()])}if(chatTimer)window.clearInterval(chatTimer);if(chatRefreshTimer)window.clearInterval(chatRefreshTimer);visibleDanmaku.value=[];if(v){chatPage.value=0;await loadChat();await nextTick();startPlayer();chatTimer=window.setInterval(fireDanmaku,500)}});watch(livePlayback,v=>{if(chatRefreshTimer)window.clearInterval(chatRefreshTimer);if(v&&playing.value)chatRefreshTimer=window.setInterval(()=>loadChat().then(reloadDanmaku).catch(()=>{}),10000)});onBeforeUnmount(()=>{if(chatTimer)window.clearInterval(chatTimer);if(chatRefreshTimer)window.clearInterval(chatRefreshTimer);if(livePoll)window.clearInterval(livePoll);dplayer?.destroy();hlsInstance?.destroy()})
