async function runSearch(){if(!searchQuery.value.trim()){searchResults.value={results:[],total:0};return}const p=new URLSearchParams({q:searchQuery.value,offset:String(searchOffset.value),limit:'30'});if(commonChannel.value)p.set('channel_id',String(commonChannel.value));const r=await fetch(`${base}/search/transcripts?${p}`);if(r.ok)searchResults.value=await r.json()}
