async function runTranscript(){const r=await fetch(`${base}/videos/${playing.value.id}/transcript`,{method:'POST'});if(!r.ok){transcript.value.error=await r.text();return}await loadTranscript();const timer=window.setInterval(async()=>{await loadTranscript();if(!['pending','processing','retry_wait'].includes(transcript.value.status))window.clearInterval(timer)},3000)}
