const conversions = ref<Record<string,any>>({})
function canPlayVideo(v:any){if(v.media_extension==='.mkv')return false;const el=document.createElement('video');return !v.media_extension||el.canPlayType(v.media_extension==='.mp4'?'video/mp4; codecs="av01.0.05M.08,opus"':'video/webm')!==''}
async function convert(v:any,mode:'remux'|'h264'){const key=`${v.id}:${mode}`;try{let r=await fetch(`${base}/videos/${v.id}/convert/${mode}`,{method:'POST'});let state=await r.json();conversions.value[key]=state;while(['queued','running'].includes(state.status)){await new Promise(resolve=>setTimeout(resolve,1500));r=await fetch(`${base}/videos/${v.id}/convert/${mode}`);state=await r.json();conversions.value[key]=state}if(state.status==='completed'){await load();if(mode==='remux')playing.value={...v,playable:true}}}catch(e){conversions.value[key]={status:'failed',error:String(e)}}}
