const upcomingQuery=ref(''), upcomingFrom=ref(''), upcomingTo=ref(''), channelPreview=ref<any>(null), previewError=ref('')
const upcoming = computed(()=>[...upcomingRows.value].filter(v=>(!upcomingQuery.value||`${v.title} ${v.channel_name}`.toLowerCase().includes(upcomingQuery.value.toLowerCase()))&&(!upcomingFrom.value||Date.parse(v.scheduled_start_at||'')>=Date.parse(upcomingFrom.value))&&(!upcomingTo.value||Date.parse(v.scheduled_start_at||'')<=Date.parse(upcomingTo.value+'T23:59:59'))).sort((a,b)=>(Date.parse(a.scheduled_start_at||'2999')-Date.parse(b.scheduled_start_at||'2999'))))
const channelQuery=ref(''), channelMonitorFilter=ref('all'), channelSort=ref('name')
const shownChannels=computed(()=>channels.value.filter(c=>(!channelQuery.value||`${c.name} ${c.youtube_channel_id}`.toLowerCase().includes(channelQuery.value.toLowerCase()))&&(channelMonitorFilter.value==='all'||(channelMonitorFilter.value==='on'?c.enabled:!c.enabled))).sort((a,b)=>channelSort.value==='subs'?(b.subscriber_count||0)-(a.subscriber_count||0):channelSort.value==='next'?Date.parse(a.next_check_at||'2999')-Date.parse(b.next_check_at||'2999'):channelSort.value==='recordings'?(b.recording_count||0)-(a.recording_count||0):a.name.localeCompare(b.name)))
const shownVideos = computed(()=>videos.value)
const sortChoice = computed({get:()=>`${sortMode.value}:${videoFilters.value.direction}`,set:(value:string)=>{const [sort,direction]=value.split(':');sortMode.value=sort;videoFilters.value.direction=direction}})
const pageStart=computed(()=>filteredCount.value?offset.value+1:0), pageEnd=computed(()=>Math.min(offset.value+videos.value.length,filteredCount.value))
function fmtBytes(n:number){if(!n)return '—';const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`}
function remaining(d:string){if(!d)return '時刻未定';const ms=Date.parse(d)-Date.now();if(ms<=0)return '開始時刻を過ぎています';const h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000);return h?`あと ${h}時間 ${m}分`:`あと ${m}分`}
async function refreshRecordingMetrics(rows:any[]){await Promise.all(rows.filter(v=>v.status==='RECORDING').map(async v=>{try{const response=await fetch(`${base}/videos/${v.id}/recording/monitor`);if(!response.ok)return;const m=await response.json();const size=Number(m.file_size);if(!Number.isFinite(size))return;const prev=metricPrev.value[v.id],time=Date.now();m.speed=prev&&time>prev.time?Math.max(0,(size-prev.size)*1000/(time-prev.time)):null;m.elapsed_seconds=Number.isFinite(Number(m.elapsed_seconds))?Number(m.elapsed_seconds):null;m.free_bytes=Number.isFinite(Number(m.free_bytes))?Number(m.free_bytes):null;metricPrev.value[v.id]={size,time};recordingMetrics.value[v.id]=m}catch{}}))}
async function loadArchiveVideos(){const filters={...Object.fromEntries(Object.entries(videoFilters.value).filter(([,v])=>v!=='')) as any,...(commonChannel.value?{channel_id:String(commonChannel.value)}:{})};const countParams=new URLSearchParams(filters);const countResponse=await fetch(`${base}/videos/count?${countParams}`);if(countResponse.ok){const countData=await countResponse.json();filteredCount.value=Number(countData.count)||0}else{let total=0,scanOffset=0;while(true){const scanParams=new URLSearchParams({offset:String(scanOffset),limit:'100',sort:sortMode.value,direction:videoFilters.value.direction,...filters});const response=await fetch(`${base}/videos?${scanParams}`);if(!response.ok)throw new Error('動画一覧を取得できません');const batch=await response.json();if(!Array.isArray(batch))throw new Error('動画一覧の形式が正しくありません');total+=batch.filter((v:any)=>v.has_file).length;scanOffset+=batch.length;if(batch.length<100)break}filteredCount.value=total}const params=new URLSearchParams({offset:String(offset.value),limit:String(pageSize),sort:sortMode.value,direction:videoFilters.value.direction,...filters});const response=await fetch(`${base}/videos?${params}`);if(!response.ok)throw new Error('動画一覧を取得できません');videos.value=await response.json();await refreshRecordingMetrics(videos.value)}
async function load(){try{[channels.value,storages.value,qualityPresets.value]=await Promise.all(['channels','storages','quality-presets'].map(x=>fetch(`${base}/${x}`).then(r=>r.json())));storageUsage.value=await fetch(`${base}/storages/usage`).then(r=>r.json());upcomingRows.value=await fetch(`${base}/videos?scope=upcoming&limit=100${commonChannel.value?`&channel_id=${commonChannel.value}`:''}`).then(r=>r.json());if(tab.value==='analysis'&&!analysisChannel.value&&channels.value.length){analysisChannel.value=channels.value[0].id;loadAnalysis()}await loadArchiveVideos()}catch{error.value='API に接続できません。backend の起動状態を確認してください。'}}
