function resetRule(){ruleEditing.value=null;rulePreview.value=null;ruleForm.value={name:'',pattern:'',target:'both',match_mode:'keyword',is_exclusion:false,case_sensitive:false,channel_id:null,enabled:true,storage_id:null,retention_days:null,quality:null,edit_detection_mode:null,priority:100}}
function editRule(rule:any){ruleEditing.value=rule.id;rulePreview.value=null;ruleForm.value={...rule}}
