async function previewRule(){const r=await fetch(`${base}/recording-rules/preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(ruleForm.value)});const d=await r.json();if(!r.ok){error.value=d.error||'プレビューを取得できません';return}rulePreview.value=d}
async function removeRule(id:number){if(!confirm('このルールを削除しますか？'))return;const r=await fetch(`${base}/recording-rules/${id}`,{method:'DELETE'});if(!r.ok){error.value='ルールを削除できません';return}await loadRules()}
async function previewChannel(){previewError.value='';channelPreview.value=null;try{const r=await fetch(`${base}/channels/preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:form.value.url})});const data=await r.json();if(!r.ok)throw new Error(data.error||'プレビューを取得できません');channelPreview.value=data;form.value.name=data.name;form.value.youtube_channel_id=data.channel_id;form.value.url=data.url}catch(e){previewError.value=String(e)}}
async function fetchFormats(){formatError.value='';availableFormats.value='';try{const r=await fetch(`${base}/formats/${encodeURIComponent(formatVideoId.value.trim())}`);const data=await r.json();if(!r.ok)throw new Error(data.error||'取得に失敗しました');availableFormats.value=data.formats}catch(e){formatError.value=String(e)}}
async function submitChannel(edit=false){error.value='';const id=editing.value;if(!id&&!form.value.name)form.value.name=channelPreview.value?.name||'YouTube チャンネル';const r=await fetch(id?`${base}/channels/${id}`:`${base}/channels`,{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify((()=>{const x={...(edit?channelForm.value:form.value)};if(x.live_quality==='custom')x.live_quality=x.live_quality_custom||'';if(x.archive_quality==='custom')x.archive_quality=x.archive_quality_custom||'';delete x.live_quality_custom;delete x.archive_quality_custom;return x})())});if(!r.ok){error.value=await r.text();return}editing.value=null;form.value={...defaults};channelForm.value={...defaults};await load()}
function editChannel(c:any){editing.value=c.id;const known=(v:string)=>qualityPresets.value.some(p=>p.id===v||p.selector===v);channelForm.value={...defaults,...c,live_quality:known(c.live_quality)?(qualityPresets.value.find(p=>p.id===c.live_quality||p.selector===c.live_quality)?.selector??''): 'custom',archive_quality:known(c.archive_quality)?(qualityPresets.value.find(p=>p.id===c.archive_quality||p.selector===c.archive_quality)?.selector??''): 'custom',live_quality_custom:known(c.live_quality)?'':c.live_quality,archive_quality_custom:known(c.archive_quality)?'':c.archive_quality}}
async function removeChannel(id:number){if(!confirm('このチャンネルの監視を停止しますか？録画履歴は保持されます。'))return;await fetch(`${base}/channels/${id}`,{method:'DELETE'});await load()}
async function refreshChannel(id:number){const r=await fetch(`${base}/channels/${id}/refresh-metadata`,{method:'POST'});if(!r.ok)error.value=await r.text();await load()}
async function clearVideoFilters(){videoFilters.value={q:'',status:'',protection_reason:'',from:'',to:'',min_size:'',max_size:'',storage_id:'',permanent:'',direction:'desc'};sortMode.value='date';offset.value=0;load()}
async function addStorage(){const r=await fetch(`${base}/storages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(storageForm.value)});if(!r.ok){error.value=await r.text();return}storageForm.value={name:'',root_path:'',minimum_free_bytes:0,warning_free_bytes:0};await load()}
async function action(id:number,path:string,method='POST'){const r=await fetch(`${base}/videos/${id}/${path}`,{method});if(!r.ok)error.value=await r.text();await load()}
async function deleteVideo(v:any){if(!confirm(`「${v.title||v.youtube_video_id}」の録画ファイルを手動削除します。元に戻せません。よろしいですか？`))return;const r=await fetch(`${base}/videos/${v.id}`,{method:'DELETE'});if(!r.ok)error.value=await r.text();await load()}
async function page(delta:number){offset.value=Math.max(0,offset.value+delta*pageSize);await load()}
async function loadAnalysis(){if(!analysisChannel.value){analysis.value=null;return}const days=analysisPeriod.value==='all'?null:Number(analysisPeriod.value);const from=days?new Date(Date.now()-days*86400000).toISOString():new Date(0).toISOString();const query=new URLSearchParams({granularity:days&&days<=90?'day':days?'week':'month',from});try{const r=await fetch(`${base}/channels/${analysisChannel.value}/stats?${query}`);if(!r.ok)throw new Error(await r.text());analysis.value=await r.json();analysisError.value=''}catch(e){analysisError.value=String(e);analysis.value=null}}
function chartPath(points:any[],key:string){const values=points.map(p=>p[key] as number|null),nums=values.filter((v):v is number=>v!==null);if(!nums.length)return '';const min=Math.min(...nums),max=Math.max(...nums),range=max-min||1,w=560,h=180,pad=14;let path='',segment=false;values.forEach((v,i)=>{if(v===null){segment=false;return}const x=pad+(points.length<2?(w-2*pad)/2:i*(w-2*pad)/(points.length-1)),y=h-pad-(v-min)*(h-2*pad)/range;path+=`${segment?'L':'M'}${x},${y} `;segment=true});return path}
function chartX(i:number,n:number){return 14+(n<2?266:i*532/(n-1))}function chartY(points:any[],key:string,v:number){const ns=points.map(p=>p[key]).filter((x:number|null)=>x!==null) as number[];const min=Math.min(...ns),max=Math.max(...ns);return 166-(v-min)/(max-min||1)*152}
function hasSeries(key:string){return !!analysis.value?.points.some((point:any)=>point[key]!==null)}
function seriesCount(key:string){return analysis.value?.points.filter((point:any)=>point[key]!==null).length||0}
function dateRange(days:string){if(days==='all')return null;return new Date(Date.now()-Number(days)*86400000).toISOString()}
onMounted(()=>{window.addEventListener('popstate',restoreQuery);if(!new URLSearchParams(location.search).has('tab'))syncQuery();if(commonChannel.value)localStorage.setItem('yla-channel',String(commonChannel.value));load();videoRefreshTimer=window.setInterval(()=>{if(tab.value==='videos')loadArchiveVideos().catch(()=>{})},5000)})
</script>
<template><main><header><div><small>ARCHIVE CONTROL</small><h1>YouTube Live Archiver</h1></div><button class="refresh" @click="load">更新 ↻</button></header>
<nav><button v-for="t in [['channels','チャンネル'],['upcoming','配信予定'],['videos','動画アーカイブ'],['search','全文検索'],['storages','ストレージ'],['analysis','分析'],['settings','設定'] ]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0];if(t[0]==='analysis'){if(!analysisChannel&&channels.length)analysisChannel=channels[0].id;loadAnalysis()}if(t[0]==='settings'){loadTranscriptionSettings();loadRules()}">{{t[1]}}</button></nav><div class="toolbar channel-filter"><label>チャンネル選択 <select :value="commonChannel" @change="setCommonChannel(($event.target as HTMLSelectElement).value ? Number(($event.target as HTMLSelectElement).value) : null)"><option value="">全チャンネル</option><option v-for="c in channels" :key="c.id" :value="c.id">{{c.has_avatar?'●':'◉'}} {{c.name}}</option></select></label></div><p v-if="error" class="error">{{error}}</p>
<section v-if="tab==='search'"><div class="heading"><div><h2>文字起こし全文検索</h2><p>録画の発言をチャンネル横断で検索</p></div></div><div class="toolbar search-toolbar"><label>キーワード<input v-model="searchQuery" @keyup.enter="searchOffset=0;runSearch()" placeholder="検索語"></label><button class="primary" @click="searchOffset=0;runSearch()">検索</button><span>{{searchResults.total}} 件 · {{searchResults.engine||''}}</span></div><p v-if="!searchQuery" class="empty">検索語を入力して検索してください。</p><p v-else-if="searchResults.total===0" class="empty">該当する発言はありません。</p><article v-for="item in searchResults.results" :key="item.video_id+'-'+item.start" class="card list"><button class="plain" @click="playSearchResult(item)"><b>{{item.title}}</b><small>{{item.channel_name}} · {{item.time}}</small><span>{{item.excerpt.before}}<mark>{{item.excerpt.match}}</mark>{{item.excerpt.after}}</span></button></article><button v-if="searchOffset+30<searchResults.total" @click="searchOffset+=30;runSearch()">次の30件</button></section>
<section v-if="tab==='channels'"><div class="toolbar"><input v-model="channelQuery" placeholder="チャンネル検索"><select v-model="channelMonitorFilter"><option value="all">監視状態すべて</option><option value="on">監視 ON</option><option value="off">監視 OFF</option></select><select v-model="channelSort"><option value="name">名前順</option><option value="subs">登録者数順</option><option value="next">次回確認時刻順</option><option value="recordings">録画本数順</option></select><span>{{shownChannels.length}} 件</span></div><div class="heading"><div><h2>監視チャンネル</h2><p>監視設定と取得したチャンネル情報</p></div><span class="count">{{channels.length}} チャンネル</span></div>
<div v-if="!shownChannels.length" class="empty">{{channels.length?'条件に一致するチャンネルはありません。':'チャンネルが登録されていません。'}}</div><article class="card channel" v-for="c in shownChannels" :key="c.id"><img v-if="c.has_avatar" :src="`${base}/channels/${c.id}/avatar`" class="avatar"><div v-else class="avatar placeholder">▶</div><div class="grow"><b>{{c.name}}</b><small>{{c.youtube_channel_id}} · {{c.enabled?'監視中':'停止中'}} · {{c.subscriber_count?.toLocaleString()||'登録者数不明'}} · 過去分 {{c.backfill_limit}} 本</small><small>{{c.description}}</small></div><span>{{c.retention_days??'∞'}} 日</span><span>{{storages.find(s=>s.id===c.storage_id)?.name||'Default'}}</span><button class="plain" @click="refreshChannel(c.id)">情報更新</button><button class="plain" @click="editChannel(c)">編集</button><button class="plain" @click="removeChannel(c.id)">監視解除</button></article>
<div class="card form"><h3>{{editing?'チャンネル設定':'チャンネル追加'}}</h3><label class="registration">チャンネル URL / @handle / チャンネル ID<input v-model="form.url" placeholder="https://youtube.com/@example または @example / UC…"><button class="plain" @click="previewChannel">プレビュー</button><button class="primary" @click="submitChannel()">登録</button><img v-if="channelPreview?.avatar" :src="channelPreview.avatar" class="avatar"><span v-if="channelPreview">{{channelPreview.name}} · {{channelPreview.channel_id}}</span><span v-if="previewError" class="error">{{previewError}}</span></label><details><summary>詳細設定</summary><div class="fields"><label>表示名<input v-model="(editing?channelForm:form).name" placeholder="チャンネル名"></label><label>YouTube チャンネル ID<input v-model="(editing?channelForm:form).youtube_channel_id" placeholder="UC…"></label><label>チャンネル URL<input v-model="(editing?channelForm:form).url" placeholder="URL / @handle"></label><select aria-label="監視状態" v-model="(editing?channelForm:form).enabled"><option :value="true">監視 ON</option><option :value="false">監視 OFF</option></select><select aria-label="通常監視間隔（分）" v-model="(editing?channelForm:form).poll_interval"><option value="30">30分</option><option value="45">45分</option><option value="60">60分</option><option>AUTO</option></select><label>保存期間（日、空欄=永久）<input v-model.number="(editing?channelForm:form).retention_days" type="number" placeholder="日数"></label><label>過去配信の取込数（本）<input v-model.number="(editing?channelForm:form).backfill_limit" type="number" min="0" placeholder="0=なし"></label><label><input type="checkbox" v-model="(editing?channelForm:form).chat_enabled">ライブチャット保存 ON</label><label><input type="checkbox" v-model="(editing?channelForm:form).live_playback_enabled">録画中の追っかけ視聴（既定 OFF）</label><label>HLS 上限 (bytes)<input aria-label="HLS 上限 bytes" type="number" min="0" v-model.number="(editing?channelForm:form).live_playback_limit_bytes"></label><label>削除猶予（日）<input v-model.number="(editing?channelForm:form).deletion_grace_days" type="number" placeholder="日数"></label><select aria-label="保存先" v-model="(editing?channelForm:form).storage_id"><option :value="null">Default Storage</option><option v-for="s in storages" :value="s.id">{{s.name}}</option></select><select aria-label="予備保存先" v-model="(editing?channelForm:form).fallback_storage_id"><option :value="null">Fallback なし</option><option v-for="s in storages" :value="s.id">{{s.name}}</option></select><label>ライブ画質<select aria-label="ライブ画質" v-model="(editing?channelForm:form).live_quality"><option v-for="p in qualityPresets" :key="p.id" :value="p.selector">{{p.label}}</option><option value="custom">カスタム</option></select><small>{{qualityPresets.find(p=>p.selector===(editing?channelForm:form).live_quality)?.description}}</small><label v-if="(editing?channelForm:form).live_quality==='custom'">カスタムライブ画質<input v-model="(editing?channelForm:form).live_quality_custom" placeholder="yt-dlp format selector"></label></label><label>アーカイブ画質<select aria-label="アーカイブ画質" v-model="(editing?channelForm:form).archive_quality"><option v-for="p in qualityPresets" :key="p.id" :value="p.selector">{{p.label}}</option><option value="custom">カスタム</option></select><small>{{qualityPresets.find(p=>p.selector===(editing?channelForm:form).archive_quality)?.description}}</small><label v-if="(editing?channelForm:form).archive_quality==='custom'">カスタムアーカイブ画質<input v-model="(editing?channelForm:form).archive_quality_custom" placeholder="yt-dlp format selector"></label></label><label>Cookie Profile<input v-model="(editing?channelForm:form).cookie_profile" placeholder="Cookie ファイル / chrome:Profile"></label><select aria-label="編集検出モード" v-model="(editing?channelForm:form).edit_detection_mode"><option value="off">OFF</option><option value="basic">Basic</option><option value="standard">Standard</option><option value="strong">Strong</option></select><label><input v-model="(editing?channelForm:form).always_protect" type="checkbox"> 🔒 常に永久保存</label></div><button class="primary" @click="submitChannel()">{{editing?'設定を保存':'詳細設定で登録'}}</button></details><button v-if="editing" class="plain" @click="editing=null">キャンセル</button></div></section>
<section v-if="tab==='analysis'"><div class="heading"><div><h2>チャンネル分析</h2><p>取得した時点の統計と録画実績</p></div></div><div class="toolbar"><select v-model.number="analysisChannel" @change="loadAnalysis"><option :value="null">チャンネルを選択</option><option v-for="c in channels" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="analysisPeriod" @change="loadAnalysis"><option value="30">30日</option><option value="90">90日</option><option value="365">1年</option><option value="all">全期間</option></select></div><p v-if="analysisError" class="error">{{analysisError}}</p><div v-if="!channels.length" class="empty">チャンネルを登録してください。</div><template v-if="analysis"><div class="stats-summary"><article class="card metric"><small>現在の登録者数（取得値）</small><b>{{analysis.current?.subscriber_count?.toLocaleString()??'未取得'}}</b><small v-if="analysis.current?.subscriber_count_rounded">YouTube の表示値のため丸めの可能性があります</small><small>前日 {{analysis.deltas.day.subscriber_count?.toLocaleString()??'未取得'}} · 前週 {{analysis.deltas.week.subscriber_count?.toLocaleString()??'未取得'}} · 前月 {{analysis.deltas.month.subscriber_count?.toLocaleString()??'未取得'}}</small></article><article class="card metric"><small>動画本数 / 総再生回数</small><b>{{analysis.current?.video_count?.toLocaleString()??'未取得'}} / {{analysis.current?.view_count?.toLocaleString()??'未取得'}}</b><small>前日 {{analysis.deltas.day.video_count?.toLocaleString()??'未取得'}} 本 / {{analysis.deltas.day.view_count?.toLocaleString()??'未取得'}} 回 · 前週 {{analysis.deltas.week.video_count?.toLocaleString()??'未取得'}} 本 / {{analysis.deltas.week.view_count?.toLocaleString()??'未取得'}} 回 · 前月 {{analysis.deltas.month.video_count?.toLocaleString()??'未取得'}} 本 / {{analysis.deltas.month.view_count?.toLocaleString()??'未取得'}} 回</small></article></div><div v-for="series in [{key:'subscriber_count',label:'登録者数'},{key:'video_count',label:'動画本数'},{key:'view_count',label:'総再生回数'}]" :key="series.key" class="card chart-card"><h3>{{series.label}}の推移</h3><div v-if="seriesCount(series.key)<2" class="empty">データを蓄積中です（記録点 {{seriesCount(series.key)}} 件）。過去の値はありません。</div><svg v-if="hasSeries(series.key)" viewBox="0 0 560 180" role="img" :aria-label="series.label+'の推移'"><line v-for="y in [30,75,120,166]" :key="y" x1="14" :y1="y" x2="546" :y2="y" class="gridline"/><path :d="chartPath(analysis.points,series.key)" class="chartline"/><circle v-for="(point,i) in analysis.points" :key="i" :cx="chartX(i,analysis.points.length)" :cy="point[series.key]===null?0:chartY(analysis.points,series.key,point[series.key])" :opacity="point[series.key]===null?0:1" r="3.5" class="chartdot"><title>{{new Date(point.captured_at).toLocaleString()}} · {{point[series.key]?.toLocaleString()}}</title></circle></svg><div class="chart-labels"><span v-if="analysis.points.length">{{new Date(analysis.points[0].captured_at).toLocaleDateString()}}</span><span v-if="analysis.points.length">{{new Date(analysis.points[analysis.points.length-1].captured_at).toLocaleDateString()}}</span></div></div><div class="heading"><div><h2>録画統計</h2><p>選択期間内</p></div></div><div class="stats-summary"><article class="card metric"><small>録画本数</small><b>{{analysis.recordings.count.toLocaleString()}}</b></article><article class="card metric"><small>録画総容量</small><b>{{fmtBytes(analysis.recordings.total_bytes)}}</b></article><article class="card metric"><small>保護済み本数</small><b>{{analysis.recordings.protected_count.toLocaleString()}}</b><small>{{Object.entries(analysis.recordings.protected_reasons).map(([k,v])=>`${k}: ${v}`).join(' · ')||'内訳なし'}}</small></article><article class="card metric"><small>平均配信時間</small><b>{{analysis.recordings.average_duration_seconds===null?'未集計':`${(analysis.recordings.average_duration_seconds/3600).toFixed(1)} 時間`}}</b></article></div></template></section>
<section v-if="tab==='upcoming'"><div class="toolbar"><input v-model="upcomingQuery" placeholder="配信予定・チャンネル検索"><label>開始日<input type="date" v-model="upcomingFrom"></label><label>終了日<input type="date" v-model="upcomingTo"></label><button class="plain" @click="upcomingQuery='';upcomingFrom='';upcomingTo=''">解除</button></div><div class="heading"><div><h2>配信予定</h2><p>開始予定時刻の近い順 · UPCOMING / LIVE</p></div><span class="count">{{upcoming.length}} 件</span></div><div v-if="!upcoming.length" class="empty">現在、配信予定はありません。</div><article class="card upcoming" v-for="v in upcoming" :key="v.id"><img v-if="v.thumbnail_url" :src="v.thumbnail_url"><div class="grow"><b>{{v.title||v.youtube_video_id}}</b><small>{{v.channel_name}} · {{v.scheduled_start_at?new Date(v.scheduled_start_at).toLocaleString():remaining(v.scheduled_start_at)}}</small></div><a class="plain link touch" :href="`https://youtube.com/watch?v=${v.youtube_video_id}`" target="_blank">YouTube で開く</a><button class="plain touch" @click="action(v.id, v.raw_metadata?.schedule_enabled===false?'schedule/enable':'schedule/disable')">{{v.raw_metadata?.schedule_enabled===false?'録画する':'録画しない'}}</button><button class="plain touch" @click="action(v.id,'recording/try')">今すぐ録画</button></article></section><section v-if="tab==='videos'">
<div class="heading"><div><h2>動画アーカイブ</h2><p>録画ファイル・保持期限・保護状態</p></div><span class="count">{{filteredCount}} 件</span></div><div class="fields filter-grid"><label>キーワード<input v-model="videoFilters.q" placeholder="タイトル・説明"></label><label>状態<select v-model="videoFilters.status"><option value="">すべて</option><option>ACTIVE</option><option>RECORDING</option><option>RECORDING_FAILED</option><option>PROTECTED</option><option>SKIPPED</option><option>DISCOVERED</option><option>WAITING_LIVE</option></select></label><label>保護理由<input v-model="videoFilters.protection_reason" placeholder="REMOTE_PRIVATE など"></label><label>開始日<input type="date" v-model="videoFilters.from"></label><label>終了日<input type="date" v-model="videoFilters.to"></label><label>最小サイズ (bytes)<input type="number" v-model="videoFilters.min_size"></label><label>最大サイズ (bytes)<input type="number" v-model="videoFilters.max_size"></label><label>保存先<select v-model="videoFilters.storage_id"><option value="">すべて</option><option v-for="st in storages" :value="st.id">{{st.name}}</option></select></label><label>保存期限<select v-model="videoFilters.permanent"><option value="">すべて</option><option value="true">永久</option><option value="false">期限あり</option></select></label><label>並び順<select v-model="sortChoice"><option value="date:desc">録画日時・新しい順</option><option value="date:asc">録画日時・古い順</option><option value="size:desc">サイズ・大きい順</option><option value="size:asc">サイズ・小さい順</option><option value="duration:desc">配信時間・長い順</option><option value="duration:asc">配信時間・短い順</option><option value="title:asc">タイトル・昇順</option><option value="title:desc">タイトル・降順</option></select></label><button class="plain touch" @click="clearVideoFilters">絞り込み解除</button></div><div class="toolbar pagination"><button class="plain touch" @click="page(-1)" :disabled="offset===0">前へ</button><span>{{pageStart}}–{{pageEnd}} / 全{{filteredCount}}件</span><button class="plain touch" @click="page(1)" :disabled="offset+videos.length>=filteredCount">次へ</button></div><div v-if="!videos.length" class="empty">条件に一致する動画アーカイブはありません。</div>
<article class="card video" v-for="v in shownVideos" :key="v.id"><img v-if="v.has_thumbnail||v.thumbnail_url||v.raw_metadata?.thumbnail" :src="v.has_thumbnail?`${base}/videos/${v.id}/thumbnail`:v.thumbnail_url||v.raw_metadata?.thumbnail" class="thumb"><div v-else class="thumb placeholder">▶</div><div class="grow"><b>{{v.title||v.youtube_video_id}}</b><small>{{v.channel_name}} · {{v.recorded_at?new Date(v.recorded_at).toLocaleString():'未録画'}} · {{v.status}}</small><small>{{v.original_duration?`${Math.floor(v.original_duration/60)}分`:''}} · {{(v.file_size?fmtBytes(v.file_size):v.status==='RECORDING'?'計測中':'サイズ不明')}} · {{v.storage_name||'保存先なし'}}</small><small>{{v.protected?'🔒 '+v.protection_reason:'未保護'}} · 保存期限 {{v.retention_expires_at?new Date(v.retention_expires_at).toLocaleDateString():'永久'}}</small><small v-if="v.status==='RECORDING'&&recordingMetrics[v.id]">経過 {{recordingMetrics[v.id].elapsed_seconds===null?'未取得':`${Math.floor(recordingMetrics[v.id].elapsed_seconds/60)} 分`}} · サイズ {{recordingMetrics[v.id].file_size?fmtBytes(recordingMetrics[v.id].file_size):'計測中'}} · 書込 {{recordingMetrics[v.id].speed===null?'計測中':fmtBytes(recordingMetrics[v.id].speed)+'/秒'}} · 空き {{recordingMetrics[v.id].free_bytes===null?'未取得':fmtBytes(recordingMetrics[v.id].free_bytes)}} · heartbeat {{recordingMetrics[v.id].heartbeat_at?new Date(recordingMetrics[v.id].heartbeat_at).toLocaleTimeString():'未取得'}}</small><small v-if="recordingMetrics[v.id]?.last_error" class="note">直近エラー: {{recordingMetrics[v.id].last_error}}</small><small v-if="v.media_extension==='.mkv'" class="note">{{canPlayVideo(v)?'このブラウザーで再生できます':'コンテナ非対応（MKV）です。MP4 リマックス、H.264 変換、元ファイルのダウンロードを選べます。'}}</small><small v-else-if="!canPlayVideo(v)" class="note">コーデック非対応の可能性があります。H.264 変換またはダウンロードを選べます。</small></div><div class="actions"><button v-if="v.status==='RECORDING'&&v.live_playback_available" class="plain touch" @click="playing=v;livePlayback=true;playbackMode='edge'">視聴</button><button v-if="v.has_file&&canPlayVideo(v)" class="plain touch" @click="livePlayback=false;playing=v">再生</button><button v-if="v.has_file&&v.media_extension==='.mkv'" class="plain touch" @click="convert(v,'remux')">{{conversions[`${v.id}:remux`]?.status||'MP4 リマックス'}}</button><button v-if="v.has_file&&!canPlayVideo(v)" class="plain touch" @click="convert(v,'h264')">{{conversions[`${v.id}:h264`]?.status||'H.264 + AAC 変換'}}</button><a v-if="v.has_file" class="plain link touch" :href="`${base}/videos/${v.id}/file?download=true`">元ファイルをダウンロード</a><a class="plain link" :href="`https://youtube.com/watch?v=${v.youtube_video_id}`" target="_blank">YouTube</a><button v-if="v.protected&&v.protection_reason==='MANUAL'" class="plain" @click="action(v.id,'protect','DELETE')">保護解除</button><button v-else-if="!v.protected" class="plain" @click="action(v.id,'protect')">保護</button><button v-if="v.status==='RECORDING'" class="plain" @click="action(v.id,'recording/stop')">停止</button><button v-if="['RECORDING_FAILED','WAITING_FOR_STORAGE'].includes(v.status)" class="plain" @click="action(v.id,'recording/retry')">再試行</button><button v-if="v.has_file" class="danger" @click="deleteVideo(v)">削除</button></div></article>
</section><section v-if="tab==='settings'"><div class="card form format-check"><h3>利用可能なフォーマット確認</h3><label>YouTube 動画 ID<input v-model="formatVideoId" placeholder="動画 ID"></label><button class="primary" @click="fetchFormats">一覧を取得（YouTubeへ問い合わせ）</button><p v-if="formatError" class="error">{{formatError}}</p><pre v-if="availableFormats">{{availableFormats}}</pre></div><div class="heading"><div><h2>文字起こし設定</h2><p>ローカル faster-whisper 処理</p></div></div><div class="card form"><label><input type="checkbox" v-model="transcriptionSettings.transcription_enabled">自動文字起こしを有効にする</label><div class="fields"><label>モデル名<input v-model="transcriptionSettings.whisper_model"></label><label>デバイス<select v-model="transcriptionSettings.whisper_device"><option value="auto">auto</option><option value="cpu">cpu</option><option value="cuda">cuda</option></select></label><label>Compute type<input v-model="transcriptionSettings.whisper_compute_type" placeholder="auto / int8 / float16"></label><label>言語（空欄=自動）<input v-model="transcriptionSettings.whisper_language"></label><label>同時実行数<input type="number" min="1" max="8" v-model.number="transcriptionSettings.transcription_max_concurrency"></label></div><button class="primary" @click="saveTranscriptionSettings">設定を保存</button></div><div class="heading"><div><h2>LLM 要約（任意）</h2><p>有効化すると文字起こしテキストが OpenRouter 外部プロバイダーへ送信されます。いつでも無効にできます。</p></div></div><div class="card form"><label><input type="checkbox" v-model="summarySettings.summary_enabled">要約を有効にする（既定 OFF）</label><label>API キー（{{summarySettings.openrouter_api_key_set?'設定済み ••••••••':'未設定'}}）<input type="password" autocomplete="new-password" v-model="summarySettings.openrouter_api_key" placeholder="未入力なら登録済みキーを維持"></label><div class="fields"><label>OpenRouter model ID<input v-model="summarySettings.openrouter_model" placeholder="モデル ID を指定"></label><label>API Base URL<input v-model="summarySettings.openrouter_base_url"></label><label>区間分数<select v-model.number="summarySettings.summary_chunk_minutes"><option :value="15">15</option><option :value="20">20</option><option :value="30">30</option><option :value="60">60</option></select></label><label>最大同時実行<input type="number" min="1" max="4" v-model.number="summarySettings.openrouter_max_concurrency"></label><label>最大試行回数<input type="number" min="1" max="10" v-model.number="summarySettings.openrouter_max_attempts"></label></div><button class="primary" @click="saveSummarySettings">要約設定を保存</button></div><div class="heading"><div><h2>ルール録画</h2><p>タイトル・説明文に一致する配信を自動録画します。除外ルールは常に優先します。</p></div><span class="count">{{recordingRules.length}} ルール</span></div><article v-for="rule in recordingRules" :key="rule.id" class="card list"><div class="grow"><b>{{rule.name}} · {{rule.is_exclusion?'除外':'録画'}}</b><small>{{rule.pattern}} · {{rule.match_mode}} · {{rule.channel_id?channels.find(c=>c.id===rule.channel_id)?.name||'対象チャンネル':'全チャンネル'}} · {{rule.enabled?'有効':'無効'}}</small></div><button class="plain" @click="editRule(rule)">編集</button><button class="danger" @click="removeRule(rule.id)">削除</button></article><div class="card form"><h3>{{ruleEditing?'ルール編集':'ルール追加'}}</h3><div class="fields"><label>ルール名<input v-model="ruleForm.name" placeholder="例: 定期配信"></label><label>キーワード / 正規表現<input v-model="ruleForm.pattern" placeholder="例: 雑談|歌枠"></label><label>対象<select v-model="ruleForm.target"><option value="both">タイトル・説明</option><option value="title">タイトル</option><option value="description">説明文</option></select></label><label>照合方式<select v-model="ruleForm.match_mode"><option value="keyword">キーワードを含む</option><option value="regex">正規表現</option></select></label><label>チャンネル<select v-model="ruleForm.channel_id"><option :value="null">全チャンネル</option><option v-for="c in channels" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>保存先<select v-model="ruleForm.storage_id"><option :value="null">チャンネル設定を使用</option><option v-for="s in storages" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>保存期間（日、空欄=チャンネル設定）<input v-model.number="ruleForm.retention_days" type="number" min="0" placeholder="日数"></label><label>画質<select v-model="ruleForm.quality"><option :value="null">チャンネル設定を使用</option><option v-for="preset in qualityPresets" :key="preset.id" :value="preset.selector">{{preset.label}}</option></select></label><label>編集検出<select v-model="ruleForm.edit_detection_mode"><option :value="null">チャンネル設定を使用</option><option value="off">OFF</option><option value="basic">Basic</option><option value="standard">Standard</option><option value="strong">Strong</option></select></label><label>優先順位<input v-model.number="ruleForm.priority" type="number"></label><label><input v-model="ruleForm.is_exclusion" type="checkbox">除外ルール（一致した配信を録画しない）</label><label><input v-model="ruleForm.case_sensitive" type="checkbox">大文字・小文字を区別</label><label><input v-model="ruleForm.enabled" type="checkbox">有効</label></div><div class="toolbar"><button class="primary" @click="saveRule">保存</button><button class="plain" @click="previewRule">既存動画でプレビュー</button><button class="plain" @click="resetRule">新規入力</button><span v-if="rulePreview">{{rulePreview.count}} 件一致（最大20件を表示）</span></div><div v-if="rulePreview" class="chat-list"><div v-for="v in rulePreview.videos" :key="v.id" class="chat-row">{{v.title}} · {{v.status}}</div></div></div></section><section v-if="tab==='storages'"><div class="heading"><div><h2>ストレージ</h2><p>録画ファイルの保存先</p></div></div><div v-if="!storages.length" class="empty">保存先がありません。</div><div class="card list" v-for="s in storages" :key="s.id"><div class="grow"><b>{{s.name}}</b><small>{{s.root_path}}</small><div v-if="storageUsage.find(u=>u.id===s.id)" class="storage-summary"><div class="storage-bar"><i :style="{width:storageUsage.find(u=>u.id===s.id).total_bytes?`${100*storageUsage.find(u=>u.id===s.id).used_bytes/storageUsage.find(u=>u.id===s.id).total_bytes}%`:'0%'}"></i><em :style="{width:storageUsage.find(u=>u.id===s.id).total_bytes?`${100*storageUsage.find(u=>u.id===s.id).app_bytes/storageUsage.find(u=>u.id===s.id).total_bytes}%`:'0%'}"></em></div><small>総容量 {{fmtBytes(storageUsage.find(u=>u.id===s.id).total_bytes)}} · 使用 {{fmtBytes(storageUsage.find(u=>u.id===s.id).used_bytes)}} · 空き {{fmtBytes(storageUsage.find(u=>u.id===s.id).free_bytes)}} · 本アプリ {{fmtBytes(storageUsage.find(u=>u.id===s.id).app_bytes)}} <b v-if="storageUsage.find(u=>u.id===s.id).critical" class="warn">最低空き容量未満</b><b v-else-if="storageUsage.find(u=>u.id===s.id).warning" class="warn">警告空き容量未満</b></small></div></div><span>{{s.enabled?'有効':'無効'}}</span></div><div class="card form"><h3>保存先を追加</h3><div class="fields"><label>保存先名<input v-model="storageForm.name" placeholder="名前"></label><label>保存先パス<input v-model="storageForm.root_path" placeholder="絶対パス"></label><label>最低空き容量（bytes）<input v-model.number="storageForm.minimum_free_bytes" type="number"></label><label>警告する空き容量（bytes）<input v-model.number="storageForm.warning_free_bytes" type="number"></label></div><button class="primary" @click="addStorage">ストレージ登録</button></div></section>
<div v-if="playing" class="modal" @click.self="playing=null;livePlayback=false"><div class="player"><button class="close" @click="playing=null;livePlayback=false">閉じる ×</button><h3>{{playing.title}}</h3><div v-if="livePlayback" class="toolbar"><button @click="playbackMode='catchup'">追っかけ</button><button @click="jumpLive">ライブに戻る</button><span v-if="liveDelay!==null">ライブエッジから {{liveDelay.toFixed(1)}} 秒</span></div><div class="video-stage"><div class="dplayer-mount" :class="{'danmaku-off':!danmakuOn}" :style="{'--danmaku-opacity':chatOpacity,'--danmaku-size':chatFont+'px','--danmaku-area':chatArea+'%'}"></div></div><div class="toolbar"><label><input type="checkbox" v-model="danmakuOn">弾幕</label><label>不透明度<input type="range" min="0.1" max="1" step="0.05" v-model.number="chatOpacity"></label><label>速度<input type="range" min="5" max="30" v-model.number="chatSpeed" @change="dplayer?.danmaku?.speed(12/chatSpeed)"></label><label>領域<input type="range" min="30" max="100" v-model.number="chatArea"></label><label>文字<input type="range" min="12" max="36" v-model.number="chatFont"></label><button @click="showDeleted=!showDeleted;loadChat()">削除済切替</button></div><div class="toolbar"><input v-model="chatQuery" placeholder="本文・投稿者検索" @input="chatPage=0;loadChat()"><select v-model="chatKind" @change="chatPage=0;loadChat()"><option value="">全種別</option><option value="superchat">スーパーチャット</option><option value="membership">メンバー</option></select><button @click="retrieveChat">チャット再取得</button><a :href="`${base}/videos/${playing.id}/chat/export`" download>JSON export</a></div><section class="card form"><h3>要約 · {{summary.status}}</h3><p>OpenRouter を有効にすると、ローカル生成済み文字起こしテキストが外部プロバイダーへ送信されます。録画・文字起こしは要約が無効でも利用できます。</p><p v-if="summary.error" class="error">{{summary.error}}</p><template v-if="summary.summary"><h4>概要</h4><p>{{summary.summary.summary}}</p><h4>主な話題</h4><div v-for="topic in summary.summary.topics||[]" :key="topic.start+'-'+topic.title"><b>{{Math.floor(topic.start/60)}}:{{String(Math.floor(topic.start%60)).padStart(2,'0')}} {{topic.title}}</b><p>{{topic.summary}}</p></div><h4>キーワード</h4><p>{{(summary.summary.keywords||[]).join(' · ')}}</p></template><button class="plain" @click="runSummary('all')">要約を生成 / 再生成</button><button class="plain" @click="runSummary('final')">全体要約のみ再生成</button><label>別モデルで要約<input v-model="summaryModel" placeholder="OpenRouter model ID"></label><button class="plain" @click="runSummary('all',summaryModel.trim()||undefined)">指定モデルで要約</button></section><section class="card form"><h3>タイムライン</h3><p v-if="!timelineItems.length">タイムラインはありません</p><div class="chat-list"><button v-for="item in timelineItems" :key="item.start+item.title" class="chat-row" @click="seekTranscript(item.start)">{{item.time}} · {{item.title}}</button></div></section><section class="card form"><h3>文字起こし · {{transcript.status}}</h3><p v-if="transcript.error" class="error">{{transcript.error}}</p><button class="plain" @click="runTranscript">文字起こしを実行 / 再生成</button><input v-model="transcriptQuery" placeholder="文字起こし内を検索" @input="transcriptPage=0;loadTranscript()"><div class="chat-list"><button v-for="s in transcript.segments" :key="s.start+'-'+s.end" class="chat-row" @click="seekTranscript(s.start)">{{Math.floor(s.start/60)}}:{{String(Math.floor(s.start%60)).padStart(2,'0')}} · {{s.text}}</button></div><button v-if="(transcriptPage+1)*100<transcript.total" @click="transcriptPage++;loadTranscript()">次の100件</button></section><div class="chat-list"><button v-for="m in chat.messages" :key="m.id" class="chat-row" :class="{deleted:m.is_deleted}" @click="seekChat(m.offset_ms)">{{Math.floor(m.offset_ms/1000)}}秒 {{m.author_name}}: {{m.is_deleted?'[削除済] ':''}}{{m.message_text}}</button></div><button @click="chatPage++;loadChat()">次の200件</button><p>配信開始時刻との差分でローカル録画位置へ補正</p></div></div></main></template>



